    @inline(__always)
    private func checkInterleavingUpperBlocksConstantA(_ value: H.Lane) {
        let mismatches = Mismatches("interleavingUpperBlocks with a repeating \(hex(value))")
        let bInputs = Inputs.vectors(H.Vector.self, seed: 0xCB28_DB81_02A9_7D6A)
        mismatches.check(
            H.repeating(value),
            H.Vector(raw: HighwayReference.repeatingBF16(value.bitPattern)),
            "repeating"
        )
        for b in bInputs {
            mismatches.check(
                H.interleavingUpperBlocks(H.repeating(value), b),
                H.Vector(
                    raw: HighwayReference.interleavingUpperBlocksBF16(H.repeating(value).raw, b.raw)
                ),
                "b: \(describe(b))"
            )
        }
        mismatches.record()
    }

    @inline(__always)
    private func checkInterleavingUpperBlocksConstantB(_ value: H.Lane) {
        let mismatches = Mismatches("interleavingUpperBlocks with b repeating \(hex(value))")
        let aInputs = Inputs.vectors(H.Vector.self, seed: 0xC293_A580_FDD2_9D08)
        mismatches.check(
            H.repeating(value),
            H.Vector(raw: HighwayReference.repeatingBF16(value.bitPattern)),
            "repeating"
        )
        for a in aInputs {
            mismatches.check(
                H.interleavingUpperBlocks(a, H.repeating(value)),
                H.Vector(
                    raw: HighwayReference.interleavingUpperBlocksBF16(a.raw, H.repeating(value).raw)
                ),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

